-- ============================================================================
-- 3. CURRICULUM UNITS & LESSONS (en-us)
-- ============================================================================
UPDATE units SET title = 'Tes Penempatan Bahasa Inggris', description = 'Uji kalibrasi 15 soal adaptif dari tingkat A1 hingga B1 untuk menentukan titik awal belajar American English yang paling tepat.' WHERE id = 'e4000001-0000-4000-8000-000000000001';
UPDATE units SET title = 'Rutinitas Harian & Waktu Kerja', description = 'Ceritakan jadwal harian, jam mulai kuliah atau kerja dalam format a.m./p.m. khas AS, serta gunakan pola rutinitas sehari-hari untuk kebiasaan sehari-hari.' WHERE id = 'e4000001-0000-4000-8000-000000000003';
UPDATE units SET title = 'Menyatakan Kemampuan & Minta Tolong Sopan', description = 'Jelaskan keahlian kerja atau bahasa yang kamu kuasai dengan modal ''can / can''t'', serta pelajari rahasia pelafalan Amerika yang membedakan keduanya dengan tajam!' WHERE id = 'e4000001-0000-4000-8000-000000000008';
UPDATE units SET title = 'Cerita Aktivitas yang Sedang Berlangsung', description = 'Laporkan kegiatan yang sedang terjadi detik ini maupun proyek sementara minggu ini menggunakan am/is/are + verb-ing tanpa terjebak kata kerja keadaan!' WHERE id = 'e4000001-0000-4000-8000-000000000009';
UPDATE units SET title = 'Ujian Kesiapan Bahasa Inggris A1', description = 'Evaluasi menyeluruh kemampuan dasar American English tingkat A1 (membaca, menyimak, menyusun kalimat, dan berbicara) dari Unit 1 hingga Unit 10.' WHERE id = 'e4000001-0000-4000-8000-000000000012';
UPDATE units SET title = 'Menceritakan Pengalaman Masa Lalu', description = 'Ceritakan proyek masa lalu, pengalaman kuliah, dan aktivitas kemarin dengan bentuk lampau (regular -ed, irregular verbs, was/were, dan did).' WHERE id = 'e4000001-0000-4000-8000-000000000013';
UPDATE units SET title = 'Rencana Karier, Studi & Janji Masa Depan', description = 'Bedakan kapan memakai ''be going to'' untuk rencana karier/studi yang sudah matang vs ''will'' untuk keputusan spontan dan janji cepat.' WHERE id = 'e4000001-0000-4000-8000-000000000014';
UPDATE units SET title = 'Pengalaman Hidup & Pencapaian hingga Kini', description = 'Ceritakan pengalaman hidup tanpa waktu lampau spesifik (have/has + V3), kabar terbaru (just, already, yet), serta durasi hingga kini (for vs since).' WHERE id = 'e4000001-0000-4000-8000-000000000018';
UPDATE units SET title = 'Menyatakan Tujuan & Pola Kata Kerja (-ing vs to)', description = 'Kuasai kapan kata kerja kedua harus berbentuk V-ing (enjoy, finish, avoid, suggest, kata penghubung + -ing) dan kapan memakai to + V1 (decide, offer, afford, tujuan).' WHERE id = 'e4000001-0000-4000-8000-000000000021';
UPDATE units SET title = 'Merangkai Urutan Waktu & Kejadian', description = 'Rangkai urutan prosedur, rencana masa depan, dan cerita masa lalu secara runtut menggunakan when, before, after, as soon as, until, dan while.' WHERE id = 'e4000001-0000-4000-8000-000000000022';
UPDATE units SET title = 'Ujian Kesiapan Bahasa Inggris A2', description = 'Evaluasi menyeluruh kemampuan American English tingkat A2 mencakup bentuk lampau, rencana masa depan, perbandingan, bentuk "have/has + V3", dan komunikasi layanan di AS.' WHERE id = 'e4000001-0000-4000-8000-000000000023';
UPDATE units SET title = 'Masih Berdampak Kini vs Sudah Selesai di Masa Lalu', description = 'Bedakan secara tajam kapan memakai bentuk "have/has + V3" (periode waktu masih terbuka / dampak kini) dan bentuk lampau (waktu lampau selesai) dalam rapat, laporan riset, dan wawancara kerja AS.' WHERE id = 'e4000001-0000-4000-8000-000000000024';
UPDATE units SET title = 'Aktivitas yang Terus Berjalan hingga Kini', description = 'Gunakan have/has been + V-ing untuk menonjolkan proses aktivitas berdurasi yang masih berlangsung hingga kini, serta pahami bedanya dengan bentuk "have/has + V3".' WHERE id = 'e4000001-0000-4000-8000-000000000025';
UPDATE units SET title = 'Pengandaian Nyata vs Berandai-andai', description = 'Kuasai kalimat pengandaian kemungkinan nyata di masa depan (kalimat pengandaian kemungkinan nyata & unless) serta skenario hipotesis/strategis masa kini (kalimat berandai-andai soal situasi kini & If I were).' WHERE id = 'e4000001-0000-4000-8000-000000000026';
UPDATE units SET title = 'Kalimat Pasif untuk Proses & Laporan Kerja', description = 'Sampaikan prosedur ilmiah, siklus alam akademik, dan laporan insiden bisnis secara objektif menggunakan kalimat pasif (is/are + V3, was/were + V3, has been + V3, modal + be + V3).' WHERE id = 'e4000001-0000-4000-8000-000000000027';
UPDATE units SET title = 'Menjelaskan Orang, Benda & Tempat dengan "Yang"', description = 'Padatkan dua kalimat terpisah menjadi satu kalimat akademik dan profesional yang tajam menggunakan kata hubung penjelas (''yang''): who, which, that, whose, dan where.' WHERE id = 'e4000001-0000-4000-8000-000000000028';
UPDATE units SET title = 'Menyimpulkan Situasi dari Bukti Saat Ini', description = 'Tarik kesimpulan logis berdasarkan bukti yang terlihat saat ini (95% yakin benar: must, 50% mungkin: might/may/could, 95% mustahil: can''t/couldn''t).' WHERE id = 'e4000001-0000-4000-8000-000000000030';
UPDATE units SET title = 'Menyampaikan Ulang Pesan & Hasil Rapat', description = 'Teruskan pesan klien, hasil rapat, pertanyaan wawancara, dan instruksi manajer secara akurat menggunakan kalimat tidak langsung (said vs told, tense backshift, asked if/wh-, told to V1).' WHERE id = 'e4000001-0000-4000-8000-000000000031';
UPDATE units SET title = 'Bertanya Lebih Halus & Sopan di Kantor/Kampus', description = 'Ajukan pertanyaan kepada orang baru, klien, dan profesor secara sangat santun tanpa membalik subjek dan kata kerja (Could you tell me where..., Do you know if..., I was wondering...).' WHERE id = 'e4000001-0000-4000-8000-000000000032';
UPDATE units SET title = 'Menghubungkan Pertentangan & Sebab-Akibat', description = 'Kuasai perbedaan struktural kata sambung bagian kalimat vs kata penghubung sebelum kata benda untuk kontras (although/even though vs despite/in spite of) dan sebab-akibat (because/since vs because of/due to).' WHERE id = 'e4000001-0000-4000-8000-000000000033';
UPDATE units SET title = 'Ujian Kesiapan Bahasa Inggris B1', description = 'Evaluasi menyeluruh kemampuan profesional, akademik, dan kesiapan awal ujian akademik internasionaltingkat B1 dari Unit 1 hingga Unit 10.' WHERE id = 'e4000001-0000-4000-8000-000000000034';
UPDATE units SET title = 'Ungkapan Kerja & Pasangan Kata Alami Global', description = 'Kuasai frasa kata kerja tiga kata, aturan pemisahan objek kata ganti, dan pasangan kata kerja alami global untuk koordinasi lintas tim Amerika.' WHERE id = 'e5000001-0000-4000-8000-000000000001';
UPDATE units SET title = 'Menyimak Kuliah Sains & Riset Kampus', description = 'Tangkap penanda alur kuliah (lecture signposting), penyimpangan topik sementara (digressions), dan pertanyaan retoris profesor Amerika di ujian akademik internasional.' WHERE id = 'e5000001-0000-4000-8000-000000000003';
UPDATE units SET title = 'Argumen Terstruktur & Tantangan Sopan di Rapat', description = 'Sampaikan ketidaksetujuan secara diplomatis, akui poin lawan bicara dengan bagian kalimat pertentangan, dan bangun argumen rapat maupun diskusi kelas akademik.' WHERE id = 'e5000001-0000-4000-8000-000000000004';
UPDATE units SET title = 'Umpan Balik Kerja, Proyek & Kolaborasi Global', description = 'Komunikasikan kompromi arsitektur (trade-offs), utang teknis, dan umpan balik Pull Request asinkron secara konstruktif bersama tim global.' WHERE id = 'e5000001-0000-4000-8000-000000000005';
UPDATE units SET title = 'Berandai-andai soal Masa Lalu & Evaluasi Proyek', description = 'Evaluasi keputusan masa lalu, analisis post-mortem proyek, dan hubungkan sebab lampau dengan dampak saat ini menggunakan 3rd serta kalimat pengandaian sebab lampau & dampak kini.' WHERE id = 'e5000001-0000-4000-8000-000000000006';
UPDATE units SET title = 'Pembuka Kalimat Ringkas & Laporan Eksekutif', description = 'Padatkan kalimat laporan eksekutif dan esai akademikmenggunakan kalimat pembuka ringkas (-ing, V3, dan Having + V3) tanpa terjebak subjek pembuka yang tidak cocok dengan kalimat utama.' WHERE id = 'e5000001-0000-4000-8000-000000000007';
UPDATE units SET title = 'Membaca Artikel Akademik: Ide Utama & Simpulan', description = 'Kuasai strategi pembeda fakta tersurat, simpulan logis (inference), tujuan retoris penulis, dan penyederhanaan kalimat panjang pada bacaan akademik.' WHERE id = 'e5000001-0000-4000-8000-000000000009';
UPDATE units SET title = 'Membandingkan Bacaan & Kuliah secara Terpadu', description = 'Kuasai struktur kontras poin-demi-poin antara klaim artikel bacaan dan bantahan kuliah profesor untuk meraih skor tinggi di tugas sintesis bacaan dan kuliah.' WHERE id = 'e5000001-0000-4000-8000-000000000010';
UPDATE units SET title = 'Ujian Kesiapan Bahasa Inggris B2', description = 'Evaluasi komprehensif lintas empat pilar (Reading, Listening, Writing, Speaking) yang menguji penguasaan seluruh 10 unit bahasa Inggris profesional dan akademik B2.' WHERE id = 'e5000001-0000-4000-8000-000000000011';
UPDATE units SET title = 'Urutan Balik untuk Penekanan Kuat dalam Pidato', description = 'Tingkatkan daya pikat esai akademik100+, pidato eksekutif, dan publikasi ilmiah menggunakan urutan balik kata keterangan negatif untuk penekanan yang presisi.' WHERE id = 'e5000001-0000-4000-8000-000000000012';
UPDATE units SET title = 'Saran & Usulan Formal dalam Proposal Kebijakan', description = 'Kuasai pola saran & usulan formal khas American English dalam rekomendasi kebijakan publik, memo direksi, resolusi PBB, dan esai akademik.' WHERE id = 'e5000001-0000-4000-8000-000000000013';
UPDATE units SET title = 'Menyampaikan Pendapat & Klaim Ilmiah secara Halus', description = 'Gunakan menyampaikan pendapat ilmiah dengan hati-hati (arguably, compelling evidence suggests, tends to) untuk membangun argumen ilmiah bernuansa, presisi, dan tahan kritik.' WHERE id = 'e5000001-0000-4000-8000-000000000014';
UPDATE units SET title = 'Memadatkan Kalimat Akademik agar Lebih Tajam', description = 'Ubah rangkaian anak kalimat lisan yang cair menjadi frasa nomina padat berstandar jurnal akademik, laporan ekonomi, dan bacaan dan esai akademik110+.' WHERE id = 'e5000001-0000-4000-8000-000000000018';
UPDATE units SET title = 'Penekanan Awal & Keseimbangan Kalimat Akademik', description = 'Kuasai pengedepanan kata kerja / keterangan (penekanan di awal kalimat) untuk transisi antarkalimat yang mulus serta keseimbangan paralelisme mutlak pada esai akademik105+ dan ringkasan kebijakan.' WHERE id = 'e5000001-0000-4000-8000-000000000020';
UPDATE units SET title = 'Penyingkatan Kalimat Alami Tanpa Pengulangan', description = 'Hapus pengulangan kata kerja dan bagian kalimat yang kaku menggunakan substitusi ''do so'', ''if so / if not'', ''the former / the latter'', serta penyingkatan kata bantu alami tingkat C1.' WHERE id = 'e5000001-0000-4000-8000-000000000021';
UPDATE units SET title = 'Ujian Kesiapan Bahasa Inggris C1', description = 'Evaluasi komprehensif lintas empat pilar (Reading, Listening, Writing, Speaking) yang menguji kemahiran bahasa Inggris akademik, beasiswa internasional, dan kepemimpinan global C1.' WHERE id = 'e5000001-0000-4000-8000-000000000022';
UPDATE units SET title = 'Pengandaian Formal Tanpa "If" (Should, Were & Had)', description = 'Kuasai pengandaian formal tanpa "if" tingkat eksekutif, hukum, dan akademik dengan menanggalkan kata ''if'' pada skenario kontingensi, hipotesis jauh, serta kontrafaktual lampau.' WHERE id = 'e5000001-0000-4000-8000-000000000023';
UPDATE units SET title = 'Mandat Resmi, Protokol & Narasi Sejarah (be to)', description = 'Kuasai konstruksi ringkas namun sarat otoritas (''are to comply'', ''if we are to succeed'', ''was never to return'') dalam regulasi, diplomasi, dan narasi sejarah akademik.' WHERE id = 'e5000001-0000-4000-8000-000000000024';
UPDATE units SET title = 'Pembuka Latar Ringkas dalam Prosa Ilmiah & Editorial', description = 'Padatkan hubungan sebab-akibat dan rincian latar menggunakan konstruksi absolut bersubjek mandiri (''The audit completed,...'', ''Other things being equal,...'') khas majalah The Economist dan jurnal ilmiah.' WHERE id = 'e5000001-0000-4000-8000-000000000025';
UPDATE units SET title = 'Pertentangan Elegan untuk Penekanan (Much as / Though)', description = 'Bentuk konsesi bernilai sastra dan retoris tertinggi dengan mengedepankan kata sifat, kata kerja dasar, atau ''Much as'' untuk mengkritik secara elegan pada esai akademik dan tinjauan ilmiah.' WHERE id = 'e5000001-0000-4000-8000-000000000026';
UPDATE units SET title = 'Menjaga Jarak Objektif & Mengkritisi Bukti Riset', description = 'Jaga jarak intelektual dan hukum dari klaim yang belum teruji menggunakan verba skeptisisme halus (''purports to'', ''ostensibly'') serta pasif pelaporan perfek (''is alleged to have V3'').' WHERE id = 'e5000001-0000-4000-8000-000000000027';
UPDATE units SET title = 'Ungkapan Formal Klasik Pidato, Hukum & Direksi', description = 'Gunakan fosil struktur pola saran formal klasik (''Be that as it may'', ''Suffice it to say'', ''Be it... or...'', ''Far be it from me'') secara tepat konteks dalam pidato eksekutif dan esai C2.' WHERE id = 'e5000001-0000-4000-8000-000000000028';
UPDATE units SET title = 'Memperluas Kalimat Panjang dengan Jernih (Gaya Editorial)', description = 'Bangun kalimat panjang yang jernih tanpa kesalahan '', which'' kabur menggunakan aposisi pembuka, frasa perangkum di akhir kalimat (''—a flaw that...''), dan pengulangan kata kunci penjelas.' WHERE id = 'e5000001-0000-4000-8000-000000000029';
UPDATE units SET title = 'Membatasi Ruang Lingkup Argumen secara Presisi', description = 'Batasi ruang lingkup klaim hukum, ekonomi, dan filsafat sains dengan presisi bedah menggunakan penghubung tingkat C2 (''insofar as'', ''notwithstanding'', ''by the same token'').' WHERE id = 'e5000001-0000-4000-8000-000000000030';
UPDATE units SET title = 'Frasa Kerja Tiga Kata dalam Kepemimpinan AS', description = 'Kuasai idiom kerja tiga kata tak terpisahkan (''come down to'', ''live up to'', ''do away with'', ''zero in on'') yang mendominasi rapat eksekutif Amerika dan kuliah dan percakapan kampus.' WHERE id = 'e5000001-0000-4000-8000-000000000031';
UPDATE units SET title = 'Kontras Tajam & Ritme Pidato Utama Kelas Dunia', description = 'Puncaki penguasaan bahasa Inggris C2 Anda dengan kontras antitesis simetris (''less about X than about Y'', ''not by..., but by...'') serta irama tiga serangkai (irama tiga serangkai) kelas pidato kunci dunia.' WHERE id = 'e5000001-0000-4000-8000-000000000032';
UPDATE units SET title = 'Ujian Kesiapan Bahasa Inggris C2', description = 'Evaluasi puncak lintas empat pilar (Reading, Listening, Writing, Speaking) yang menguji penguasaan bahasa Inggris tingkat C-Suite, publikasi ilmiah internasional, dan skor tertinggi ujian akademik internasional.' WHERE id = 'e5000001-0000-4000-8000-000000000033';
UPDATE lessons SET title = 'Pola Kalimat: Kebiasaan & Fakta (I work vs She works)', short_title = 'Kebiasaan & Fakta' WHERE id = 'e4100001-0000-4000-8000-000000000007';
UPDATE lessons SET title = 'Pola Kalimat: Menyatakan "Ada..." & Petunjuk Arah', short_title = 'There Is/Are & Arah' WHERE id = 'e4100001-0000-4000-8000-000000000019';
UPDATE lessons SET title = 'Pola Kalimat: Rutinitas vs Sedang Berlangsung', short_title = 'Rutinitas vs Saat Ini' WHERE id = 'e4100001-0000-4000-8000-000000000031';
UPDATE lessons SET title = 'Pola Kalimat: Kata Ganti Objek (me, him, her, us, them)', short_title = 'Kata Ganti Objek' WHERE id = 'e4100001-0000-4000-8000-000000000039';
UPDATE lessons SET title = 'Pola Kalimat: Kata Kerja Lampau, Was/Were & Did', short_title = 'Bentuk Lampau & Did' WHERE id = 'e4100001-0000-4000-8000-000000000044';
UPDATE lessons SET title = 'Menyimak & Bicara: Menyatakan Tujuan (to + Kata Kerja)', short_title = 'Tujuan Studi & Karier' WHERE id = 'e4100001-0000-4000-8000-000000000049';
