UPDATE exercises SET prompt = 'Listen to the Product Lead’s interview response. What key achievement did they deliver?', content = '{"options":[{"id":"opt_1","text":"Simplified guest checkout to one tap, cutting cart abandonment by 32%"},{"id":"opt_2","text":"Removed guest checkout so every customer had to register an account"},{"id":"opt_3","text":"Allowed cart abandonment to keep rising for two more quarters"},{"id":"opt_4","text":"Raised transaction service fees by thirty-two percent"}],"audio_text":"Checkout drop-off had been climbing for months before I simplified guest payment into one tap, cutting cart abandonment by thirty-two percent."}'::jsonb, explanation = 'Cerita STAR memadukan latar ''had been climbing'', aksi ''I simplified'', dan hasil terukur ''cutting... by 32%''.' WHERE id = 'e5200001-0000-4000-8000-000000000325';
