UPDATE exercises SET prompt = 'Dengarkan kuliah etika rekayasa soal Jembatan Tacoma Narrows. Bagaimana dosen menyusun kalimat pamungkasnya?', content = '{"options":[{"id":"opt_1","text":"Menganggap verifikasi independen membuang-buang anggaran pembangunan jembatan"},{"id":"opt_2","text":"Menyatakan bahwa standar rekayasa ditulis murni berdasarkan teori matematika tanpa belajar dari kegagalan"},{"id":"opt_3","text":"Menyarankan penghapusan faktor cadangan keamanan (*redundancy*) pada jembatan gantung"},{"id":"opt_4","text":"Membuka dengan antitesis (''not in abstract ink, but in hard-won lessons...'') lalu menguncinya dengan irama tiga serangkai klimaks (''humility, redundancy, and independent verification'')"}],"audio_text":"Engineering codes are written not in abstract ink, but in the hard-won lessons of past failures—reminding every generation that humility, redundancy, and independent verification save lives."}'::jsonb WHERE id = 'e5200001-0000-4000-8000-000000000975';
