UPDATE exercises SET prompt = 'Listen to the economic history lecture on the 1880s French Panama Canal project. Why did de Lesseps’s plan fail?', content = '{"options":[{"id":"opt_1","text":"The planned sea-level canal scheduled for 1889 failed because malaria and landslides made a lockless design untenable"},{"id":"opt_2","text":"Tropical malaria had already been eliminated before French excavation began"},{"id":"opt_3","text":"De Lesseps’s lockless canal opened on schedule in 1889"},{"id":"opt_4","text":"Panama’s geology matched the flat desert terrain of the Suez Canal"}],"audio_text":"Emboldened by Suez, de Lesseps embarked upon a sea-level canal across Panama that was to have opened by 1889; tropical malaria and Chagres River landslides, however, rendered a lockless design utterly untenable."}'::jsonb WHERE id = 'e5200001-0000-4000-8000-000000000997';
UPDATE exercises SET prompt = 'Listen to the historian’s commentary on a medieval chronicle. What attitude does the historian convey?', content = '{"options":[{"id":"opt_1","text":"She accepts the medieval chronicler’s stated motives at face value"},{"id":"opt_2","text":"She exposes the contrast between pious surface rhetoric and underlying Venetian commercial rivalry"},{"id":"opt_3","text":"She argues that the expedition was driven purely by religious devotion"},{"id":"opt_4","text":"She claims Venetian merchants opposed the expedition to protect their routes"}],"audio_text":"Notice how the historian writes, ''For all the chronicler''s pious rhetoric, the crusade was ostensibly launched to secure pilgrim roads while zeroing in on Venetian commercial rivals''—she''s contrasting pious pretexts against hard trade motives!"}'::jsonb WHERE id = 'e5200001-0000-4000-8000-000000000998';
UPDATE exercises SET prompt = 'Listen to the central bank governor’s press briefing. What is the governor’s stance on cutting interest rates?', content = '{"options":[{"id":"opt_1","text":"The central bank will cut rates next week to avoid political criticism"},{"id":"opt_2","text":"Despite softer headline inflation, cutting rates without lasting wage moderation risks expectations—and the bank will accept political heat to hold steady"},{"id":"opt_3","text":"Inflation expectations do not matter for monetary policy"},{"id":"opt_4","text":"Service-sector wages have already fallen well below the bank’s target"}],"audio_text":"Headline inflation has edged down—be that as it may, absent durable moderation in service-sector wages, premature rate cuts would risk unanchoring expectations; if holding steady draws political heat, so be it."}'::jsonb, explanation = 'Menyimak rangkaian ungkapan C2: ''be that as it may'' + kata penghubung ''absent'' + penutup prinsipil ''so be it''.' WHERE id = 'e5200001-0000-4000-8000-000000000999';
UPDATE exercises SET prompt = 'Listen to the two engineering directors discussing legacy authentication retirement. What do they conclude?', content = '{"options":[{"id":"opt_1","text":"Although legacy clients resist migrating, keeping SHA-1 workarounds invites an audit nightmare, so the old stack must be retired"},{"id":"opt_2","text":"Maintaining two authentication systems simultaneously reduces security audit costs"},{"id":"opt_3","text":"Legacy enterprise clients are eager to retire the old system immediately"},{"id":"opt_4","text":"They agree to keep SHA-1 token workarounds for five more years"}],"audio_text":"Look, maintaining two auth stacks has become a double-edged sword: legacy enterprise clients hate migration, yet putting up with SHA-1 token workarounds any longer invites an audit nightmare—it''s time we did away with them."}'::jsonb, explanation = 'Memahami ''double-edged sword'', ''putting up with'', dan pola ''it''s time we did away with them'' dalam diskusi eksekutif AS.' WHERE id = 'e5200001-0000-4000-8000-000000001000';
