UPDATE exercises SET prompt = 'Arrange the tiles to craft a balanced statement that scientific authority rests less on consensus than on transparent, verifiable methods:', content = '{"romaji":"/ˌsaɪənˈtɪfɪk əˈθɔːrəti rɛsts lɛs ɑːn kənˈsɛnsəs ðæn ɑːn ˈmɛθədz trænˈspærənt ˈrɛplɪkəbəl ænd ˈoʊpən/","tokens":["open to refutation.","openly refuting","then on","Scientific authority rests","transparent, replicable, and","less on consensus","than on methods"]}'::jsonb, explanation = 'Kontras simetris ''Less on X than on Y'' ditutup dengan rangkaian tiga kata sifat berirama yang kuat.' WHERE id = 'e5200001-0000-4000-8000-000000001004';
